import React from "react";
import { useNavigate } from "react-router-dom";
import "./ProductCard.css";

const ProductCard = ({ product }) => {
    const navigate = useNavigate();

    const handleViewDetail = () => {
        // Điều hướng sang trang chi tiết theo id của sản phẩm
        navigate(`/product/${product.id}`);
    };

    // Định nghĩa link ảnh mặc định sang xịn mịn tương tự trang ProductDetail của bạn
    const defaultImage = "https://images.unsplash.com/photo-1505693416388-ac5ce068fe85";

    return (
        <div className="furniture-card h-100">

            {/* Badge */}
            <div className="furniture-badge">
                Collection
            </div>

            {/* Image */}
            <div className="furniture-img-container" onClick={handleViewDetail} style={{ cursor: 'pointer' }}>
                <img
                    src={product.imageUrl || defaultImage}
                    alt={product.name}
                    className="furniture-image"
                    onError={(e) => {
                        e.target.onerror = null;
                        e.target.src = defaultImage;
                    }}
                />
            </div>

            {/* Content */}
            <div className="furniture-content">

                <span className="furniture-category">
                    {product.categoryProductName || "Nội thất"}
                </span>

                <h3
                    className="furniture-title"
                    title={product.name}
                    onClick={handleViewDetail}
                    style={{ cursor: 'pointer' }}
                >
                    {product.name}
                </h3>

                <p className="furniture-description">
                    {product.description || "Thiết kế tinh tế, chất liệu cao cấp dành cho không gian sống hiện đại."}
                </p>

                <div className="furniture-footer">
                    <div className="furniture-price">
                        {typeof product.price === "number"
                            ? product.price.toLocaleString("vi-VN", {
                                  style: "currency",
                                  currency: "VND"
                              })
                            : product.price}
                    </div>

                    {/* Nút Xem chi tiết đã được gắn sự kiện onClick */}
                    <button className="btn-furniture" onClick={handleViewDetail}>
                        Xem chi tiết
                    </button>
                </div>

            </div>

        </div>
    );
};

export default ProductCard;
